NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Joel'

CHAPTERS = {
    1: {
        1: 'Gospodova beseda, ki je prišla Joélu, Petuélovemu sinu.',
        2: 'Poslušajte to, vi starci in pazljivo prisluhnite, vsi vi prebivalci dežele. Ali je bilo to v vaših dneh ali celo v dneh vaših očetov?',
        3: 'Pripovedujte svojim otrokom o tem in naj vaši otroci pripovedujejo svojim otrokom in njihovi otroci naslednjemu rodu.',
        4: 'To, kar je kosmata gosenica pustila, je pojedla leteča kobilica; in to, kar je leteča kobilica pustila, je pojedla škodljiva gosenica; in to, kar je pustila škodljiva gosenica, je pojedla gosenica.',
        5: 'Prebudite se, vi pijanci in jokajte, tulite vsi vi vinski pivci zaradi novega vina, kajti odrezan je od vaših ust.',
        6: 'Kajti narod je prišel nad mojo deželo, močan in brezštevilen, katerih zobje so zobje leva in ima kočnike velikega leva.',
        7: 'Opustošil je mojo trto in olupil moje figovo drevo. Naredil ga je razgaljenega in ga vrgel proč; njegove mladike so pobeljene.',
        8: 'Žalujte kakor devica, opasana z vrečevino za soprogom svoje mladosti.',
        9: 'Jedilna daritev in pitna daritev je odrezana od Gospodove hiše. Duhovniki, Gospodovi služabniki, žalujejo.',
        10: 'Polje je opustošeno, zemlja žaluje, kajti žito je opustošeno. Novo vino je posušeno, olje peša.',
        11: 'Bodite osramočeni, oh vi poljedelci. Tulite, oh vi obrezovalci trte, zaradi pšenice in zaradi ječmena, ker je žetev polja propadla.',
        12: 'Trta je posušena in figovo drevo peša. Granatovec, tudi palmovo drevo in jablana, celó vsa poljska drevesa so ovenela, ker je veselje zamrlo pred človeškimi sinovi.',
        13: 'Opašite se in objokujte, vi duhovniki; tulite, služabniki oltarja, pridite, vso noč ležite v vrečevini, vi služabniki mojega Boga, kajti jedilna daritev in pitna daritev je zadržana pred hišo vašega Boga.',
        14: 'Posvetite post, skličite slovesen zbor, zberite starešine in vse prebivalce dežele v hišo Gospoda, svojega Boga in kličite h Gospodu:',
        15: '»Gorje zaradi dneva!« Kajti dan Gospodov je pri roki in to bo prišlo kakor uničenje od Vsemogočnega.',
        16: 'Mar ni hrana odrezana izpred naših oči, da, radost in veselje od hiše našega Boga?',
        17: 'Seme je razpadlo pod njihovimi grudami, kašče ležijo zapuščene, skednji so razpadli, kajti žito je ovenelo.',
        18: 'Kako stokajo živali! Živine črede so zmedene, ker nimajo pašnika; da, tropi ovac so zapuščeni.',
        19: 'Oh Gospod, k tebi bom klical, kajti ogenj je požrl pašnike divjine in plamen je požgal vsa poljska drevesa.',
        20: 'Tudi poljske živali kličejo k tebi, kajti reke vodá so posušene in ogenj je pogoltnil pašnike divjine.',
    },
    2: {
        1: 'Zatrobite na šofar na Sionu in razglasite alarm na moji sveti gori. Naj vsi prebivalci dežele trepetajo, kajti dan Gospodov prihaja, kajti ta je blizu, pri roki;',
        2: 'dan teme in mračnosti, dan oblakov in goste teme se kot jutro razširjajo nad gorami. Veliko ljudstvo in močno, nikoli ni bilo podobnega niti ga ne bo več za tem, celó do let mnogih rodov.',
        3: 'Ogenj požira pred njimi in za njimi gori plamen. Dežela je pred njimi kakor edenski vrt in za njimi zapuščena divjina; da, in nič jim ne bo pobegnilo.',
        4: 'Njihov videz je kakor videz konjev in kakor konjeniki, tako bodo tekli.',
        5: 'Poskakovali bodo kakor hrup bojnih vozov na vrhovih gora, kakor hrup ognjenega plamena, ki požira strnišče, kakor močno ljudstvo, postavljeno v bojno razvrstitev.',
        6: 'Pred njihovim obrazom bo ljudstvo močno zaskrbljeno. Vsi obrazi bodo zbirali črnino.',
        7: 'Tekli bodo kakor mogočni možje, obzidje bodo preplezali kakor bojevniki in korakali bodo vsak po svojih poteh in svojih vrst ne bodo pretrgali.',
        8: 'Niti eden ne bo sunil drugega. Hodili bodo vsak po svoji stezi in ko padejo na meč, ne bodo ranjeni.',
        9: 'Tekali bodo sem ter tja po mestu, tekli bodo na obzidje, splezali bodo na hiše, vstopili bodo pri oknih kakor tat.',
        10: 'Zemlja se bo tresla pred njimi, nebo bo trepetalo, sonce in luna bosta otemnela in zvezde bodo umaknile svoje svetlikanje.',
        11: 'Gospod bo izustil svoj glas pred svojo vojsko, kajti njegov tabor je zelo velik, kajti on je močan, ki izvršuje svojo besedo, kajti dan Gospodov je velik in zelo strašen in kdo ga lahko prenese?',
        12: '»Zato se tudi sedaj,« govori Gospod, »obrnite celó k meni z vsem svojim srcem in s postom in z jokom in z žalovanjem',
        13: 'in pretrgajte svoje srce, ne pa svojih oblačil in obrnite se h Gospodu, svojemu Bogu, kajti on je milostljiv in usmiljen, počasen za jezo in velike prijaznosti in se kesa zla.«',
        14: 'Kdo ve, če se bo vrnil in pokesal in pustil blagoslov za seboj, celó jedilno daritev in pitno daritev Gospodu, svojemu Bogu?',
        15: 'Zatrobite na šofar na Sionu, posvetite post, skličite slovesen zbor,',
        16: 'zberite ljudstvo, posvetite skupnost, zberite starešine, naberite otroke in tiste, ki sesajo pri prsih. Naj pride ženin iz svoje sobe in nevesta iz svoje sobice.',
        17: 'Naj duhovniki, Gospodovi služabniki, jokajo med preddverjem in oltarjem in naj govorijo: »Prizanesi svojemu ljudstvu, oh Gospod in svoje dediščine ne izroči v zasmeh, da bi nad njimi vladali pogani. Zakaj bi med ljudstvom rekli: ›Kje je njihov Bog?‹«',
        18: 'Potem bo Gospod ljubosumen nad svojo deželo in se usmilil svojega ljudstva.',
        19: 'Da, Gospod bo odgovoril in rekel svojemu ljudstvu: »Glejte, poslal vam bom žito, vino in olje in nasičeni boste s tem in ne bom vas več naredil v zasmeh med pogani,',
        20: 'toda daleč od vas bom odstranil severno vojsko in pregnal jih bom v jalovo in zapuščeno deželo, s svojim obrazom proti vzhodnemu morju in s svojim zadnjim delom proti skrajnemu morju in njegov smrad se bo vzdignil in njegovo zaudarjanje se bo vzdignilo, ker je storil velike stvari.«',
        21: 'Ne boj se, oh dežela, bodi vesela in se raduj, kajti Gospod bo storil velike stvari.',
        22: 'Ne bodite prestrašene, ve poljske živali, kajti pašniki divjine poganjajo, kajti drevo rodi svoj sad, figovo drevo in trta predajata svojo moč.',
        23: 'Bodite torej veseli, vi sionski otroci in veselite se v Gospodu, svojem Bogu, kajti dal vam je zmerno prvi dež in povzročil bo, da vam bo prišel dež, prvi dež in pozni dež v prvem mesecu.',
        24: 'Tla bodo polna pšenice in kadi bodo prekipevale od vina in olja.',
        25: '»Povrnil vam bom leta, ki jih je požrla leteča kobilica, škodljiva gosenica, gosenica in kosmata gosenica, moja velika vojska, ki sem jo poslal med vas.',
        26: 'Jedli boste v obilju in boste nasičeni in slavili ime Gospoda, svojega Boga, ki je z vami čudovito ravnal in moje ljudstvo nikoli ne bo osramočeno.',
        27: 'Vedeli boste, da sem jaz v Izraelovi sredi in da sem jaz Gospod, vaš Bog in nihče drug, in moje ljudstvo nikoli ne bo osramočeno.',
        28: 'Potem se bo zgodilo, da bom svojega duha izlil na vse meso. Vaši sinovi in vaše hčere bodo prerokovali, vaši starci bodo sanjali sanje, vaši mladeniči bodo videli videnja.',
        29: 'Tudi na služabnike in na pomočnice bom v tistih dneh izlil svojega Duha.',
        30: 'Pokazal bom čudeže na nebu in na zemlji, kri in ogenj in stebre dima.',
        31: 'Sonce se bo spremenilo v temo in luna v kri pred velikim in strašnim dnevom Gospodovega prihoda.«',
        32: 'In zgodilo se bo, da kdorkoli bo klical h Gospodovemu imenu, bo osvobojen, kajti osvoboditev bo na gori Sion in v Jeruzalemu, kakor je rekel Gospod in v ostanku, ki ga bo Gospod poklical.',
    },
    3: {
        1: '»Kajti glej, v tistih dneh in v tistem času, ko bom ponovno privedel ujetništvo Juda in Jeruzalema,',
        2: 'bom prav tako zbral vse narode in jih privedel dol v dolino Józafat in tam se bom pravdal z njimi zaradi svojega ljudstva in zaradi svoje dediščine Izraela, ki so jih razkropili med narode in razdelili mojo deželo.',
        3: 'Za moje ljudstvo so metali žrebe in dajali fanta za pocestnico in punco prodajali za vino, da bi lahko pili.',
        4: 'Da, in kaj imate vi z menoj, oh Tir in Sidón in vse obale Palestine? Ali mi boste vrnili povračilo? In če mi povrnete, bom brez odlašanja in hitro vaše povračilo povrnil na vašo lastno glavo,',
        5: 'zato ker ste jemali moje srebro in moje zlato in ste v svoje templje odnesli čudovite, prijetne stvari.',
        6: 'Prav tako ste Grkom prodajali Judove otroke in jeruzalemske otroke, da bi jih lahko spravili daleč proč od njihove meje.',
        7: 'Glej, dvignil jih bom iz kraja, kamor ste jih prodali in povrnil vam bom vaše povračilo na vašo lastno glavo.',
        8: 'Vaše sinove in vaše hčere bom prodal v roko Judovih otrok in prodali jih bodo Sabejcem, ljudstvu, ki je daleč proč,« kajti Gospod je to govoril.',
        9: 'Razglasite to med pogani: »Pripravite vojno, prebudite mogočne može, naj se vsi bojevniki približajo, naj pridejo gor.',
        10: 'Prekujte svoje lemeže v meče in svoje obrezovalne kavlje v sulice. Naj slabotni reče: ›Močan sem.‹«',
        11: 'Zberite se in pridite vsi vi pogani in zberite se skupaj naokrog. Tamkaj primoraj svoje mogočne, da pridejo dol, oh Gospod.',
        12: 'Naj bodo pogani prebujeni in pridejo gor v dolino Józafat, kajti tam bom sedel, da sodim vsem poganom naokoli.',
        13: 'Nastavite srp, kajti žetev je zrela. Pridite, spustite se, kajti stiskalnica je polna, maščoba preplavlja, kajti njihova zlobnost je velika.',
        14: 'Množice, množice v dolini odločitve; kajti dan Gospodov je blizu v dolini odločitve.',
        15: 'Sonce in luna bosta otemnela in zvezde bodo umaknile svoje svetlikanje.',
        16: 'Gospod bo tudi rjovel iz Siona in izustil svoj glas iz Jeruzalema, in nebo in zemlja se bosta tresla, toda Gospod bo upanje svojemu ljudstvu in moč Izraelovim otrokom.',
        17: 'Tako boste vedeli, da jaz sem Gospod, vaš Bog, ki prebivam na Sionu, moji sveti gori. Potem bo Jeruzalem svet in nikakršni tujci ne bodo več hodili skozenj.',
        18: 'Na tisti dan se bo zgodilo, da bodo gore kapljale novo vino in z gričev se bo cedilo mleko in v vseh Judovih rekah bodo tekle vode in studenec bo izviral iz Gospodove hiše in namakal dolino Šitím.',
        19: 'Egipt bo opustošenje in Edóm bo zapuščena divjina zaradi nasilja zoper Judove otroke, ker so v njihovi deželi prelivali nedolžno kri.',
        20: 'Toda Juda bo prebival na veke in Jeruzalem od roda do roda.',
        21: 'Kajti jaz bom očistil njihovo kri, ki je nisem očistil, kajti Gospod prebiva na Sionu.',
    },
}
